function VideoOn(type,Cartesian3Array,perPositionHeight = false,planeWidth = 10) {
  const videoElement = document.getElementById("myVideo");
  let entityObject;
  switch(type){
    case "primitive":
      entityObject= window.earthviewer.scene.primitives.add(new window.cesium.GroundPrimitive({
        geometryInstances : new window.cesium.GeometryInstance({
          geometry : new window.cesium.PolygonGeometry({
            polygonHierarchy : new window.cesium.PolygonHierarchy(Cartesian3Array),
            // perPositionHeight: true //不起作用？
          })
        }),
        appearance : new window.cesium.Appearance({material: new window.cesium.Material({
          fabric : {
            type : 'Image',
            uniforms : {
              image : "http://172.20.36.34:8080/media/1.jpg"
            }
          }
        })})
      }));
      // entityObject.appearance.material.uniforms.image = "http://172.20.36.34:8080/media/video.mp4"
      break;
    case "rectangle":
      entityObject= window.earthviewer.entities.add({
        rectangle: {
          coordinates: window.cesium.Rectangle.fromCartesianArray(Cartesian3Array),
          material: videoElement,
          // extrudedHeight: undefined
        }
      });
      break;
    case "plane":
      entityObject= window.earthviewer.entities.add({
        position:Cartesian3Array[0],
        orientation: window.cesium.Transforms.headingPitchRollQuaternion(
            Cartesian3Array[0],
            new window.cesium.HeadingPitchRoll(window.earthviewer.camera.heading, 0, Math.PI/2)
          ),
        plane: {
          plane: new window.cesium.Plane(window.cesium.Cartesian3.UNIT_Z, -1.0),
          dimensions: new window.cesium.Cartesian2(planeWidth, planeWidth),
          material: videoElement,
        }
      });
      break;
    default:
      entityObject= window.earthviewer.entities.add({
        polygon: {
          hierarchy: Cartesian3Array,
          perPositionHeight: perPositionHeight,
          material: videoElement,
          heightReference: window.cesium.HeightReference.RELATIVE_TO_GROUND,
          // extrudedHeight: undefined
        }
      });
  }

  videoElement.style.display = "none";

  new window.cesium.VideoSynchronizer({
    clock: window.earthviewer.clock,
    element: videoElement
  });
  window.earthviewer.clock.shouldAnimate = true;

  return entityObject;
}

export default VideoOn;

